// Index of the group that contains x, or -1.
fn find_group(gs: List[List[Str]], x: Str) -> Int {
  for i in range(0, gs.len()) {
    if gs.get_or(i, []).contains(x) {
      return i
    }
  }
  return -1
}

pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  var gs: List[List[Str]] = []
  for p in pairs {
    let a = p.get_or(0, "")
    let b = p.get_or(1, "")
    let ia = find_group(gs, a)
    let ib = find_group(gs, b)
    if ia < 0 and ib < 0 {
      gs = gs.push([a, b])
    } else if ia < 0 {
      gs = gs.set(ib, gs.get_or(ib, []).push(a))
    } else if ib < 0 {
      gs = gs.set(ia, gs.get_or(ia, []).push(b))
    } else if ia != ib {
      let merged = gs.get_or(ia, []).concat(gs.get_or(ib, []))
      var rest: List[List[Str]] = []
      for i in range(0, gs.len()) {
        if i != ia and i != ib {
          rest = rest.push(gs.get_or(i, []))
        }
      }
      gs = rest.push(merged)
    }
  }
  var out: List[List[Str]] = []
  for g in gs {
    out = out.push(g.unique().sort())
  }
  return out.sort_by(fn(g) => g.get_or(0, ""))
}
